 const matches=ref=>{const obj=objects[ref];return !search||[obj.title,obj.summary,obj.content].some(v=>String(v||'').includes(search))||descendants(state,ref).some(r=>[objects[r]?.title,objects[r]?.summary].some(v=>String(v||'').includes(search)));};
