  if(objects[id]?.kind!=='card')return [];
  const a=p.attachment,relation=p.parent===ref?'内部':a?.ref===ref&&p.parent===state.placements[ref]?.parent?(a.position==='before'?'前面':'后面'):descendants(state,id).includes(ref)?'包围此项':null;
