 const outlineMove=e=>{const g=outlinePointer.current;if(!g||g.id!==e.pointerId)return;if(!g.moved&&Math.hypot(e.clientX-g.x,e.clientY-g.y)<5)return;g.moved=true;setOutlineGhost({title:objects[g.ref]?.title,x:e.clientX,y:e.clientY});const row=document.elementFromPoint(e.clientX,e.clientY)?.closest('.u-tree-row');if(!row){setDropTarget(null);return;}const ref=row.parentElement.dataset.outlineRef;setDropTarget(dragDestination({currentTarget:row,clientY:e.clientY},ref));const area=row.closest('.u-outline'),r=area?.getBoundingClientRect();if(r){if(e.clientY>r.bottom-28)area.scrollTop+=12;else if(e.clientY<r.top+28)area.scrollTop-=12;}};
